import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.BrO6lPIi.js";const b=JSON.parse('{"title":"认证与授权系统","description":"本文件聚焦 Agent 端（Node.js，版本 2.7.0）的认证、授权、命令执行安全、会话管理与审计日志能力。","frontmatter":{"title":"认证与授权系统","description":"本文件聚焦 Agent 端（Node.js，版本 2.7.0）的认证、授权、命令执行安全、会话管理与审计日志能力。"},"headers":[],"relativePath":"系统架构设计/Agent-服务架构/认证与授权系统/index.md","filePath":"系统架构设计/Agent-服务架构/认证与授权系统/index.md","lastUpdated":null}'),l={name:"系统架构设计/Agent-服务架构/认证与授权系统/index.md"};function o(n,e,s,g,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="认证与授权系统" tabindex="-1">认证与授权系统 <a class="header-anchor" href="#认证与授权系统" aria-label="Permalink to &quot;认证与授权系统&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js" target="_blank" rel="noreferrer">agent/src/auth.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js" target="_blank" rel="noreferrer">agent/src/logger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与安全边界总览">项目结构与安全边界总览</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源控制">性能与资源控制</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录安全配置最佳实践与审计清单">附录：安全配置、最佳实践与审计清单</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦 Agent 端（Node.js，版本 2.7.0）的认证、授权、命令执行安全、会话管理与审计日志能力。Agent 通过本地 HTTP/WebSocket 暴露接口，由 Chrome 扩展端调用；所有敏感操作均受 Bearer Token 认证、路径沙箱、命令分级白名单/黑名单以及审计日志约束。文档同时给出认证流程图、权限检查时序图、令牌生命周期图，并说明多租户支持现状、访问控制策略和安全配置建议。</p><h2 id="项目结构与安全边界总览" tabindex="-1">项目结构与安全边界总览 <a class="header-anchor" href="#项目结构与安全边界总览" aria-label="Permalink to &quot;项目结构与安全边界总览&quot;">​</a></h2><p>Agent 的安全边界由以下层次构成：</p><ul><li>网络边界：仅响应来自 <code>chrome-extension://</code> 来源的跨域请求；部分管理接口限制本机来源。</li><li>认证边界：除配对与健康检查等少数接口外，其余接口需携带 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>数据边界：配置文件、配对记录、日志、工作区、记忆目录均有独立路径与权限控制。</li><li>文件系统边界：基于规范化路径、真实路径解析与硬阻止列表的沙箱。</li><li>命令执行边界：命令分级（黑名单绝对禁止、灰名单需确认、白名单放行），子进程环境变量白名单与超时控制。</li><li>审计边界：JSON Lines 日志按日轮转，分类记录认证、文件、命令、安全与系统事件。</li></ul><pre class="mermaid">graph TB
Extension[&quot;Chrome 扩展&lt;br/&gt;side_panel / background&quot;] --&gt; HTTP[&quot;Agent HTTP 服务器&lt;br/&gt;server.js&quot;]
Extension --&gt; WS[&quot;Agent WebSocket&lt;br/&gt;server.js + executor.js&quot;]
HTTP --&gt; Auth[&quot;认证模块&lt;br/&gt;auth.js&quot;]
HTTP --&gt; Security[&quot;安全模块&lt;br/&gt;security.js&quot;]
HTTP --&gt; Logger[&quot;审计日志&lt;br/&gt;logger.js&quot;]
HTTP --&gt; Config[&quot;配置与配对&lt;br/&gt;config.js&quot;]
HTTP --&gt; Executor[&quot;命令执行器&lt;br/&gt;executor.js&quot;]
Executor --&gt; Shell[&quot;系统 Shell&lt;br/&gt;bash/zsh/cmd/powershell&quot;]
Security --&gt; FS[&quot;文件系统&lt;br/&gt;workdir / allowedPaths&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L117-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L117-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L172</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L242-L266" target="_blank" rel="noreferrer">agent/src/server.js#L242-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L8-L19" target="_blank" rel="noreferrer">agent/src/config.js#L8-L19</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>认证模块：负责配对码生成、轮换、一次性使用、失败锁定与 Token 验证。</li><li>安全模块：负责路径沙箱、硬阻止目录、白名单校验、命令分级检查。</li><li>命令执行器：负责选择 Shell、创建子进程、流式输出、超时与强制终止、进程缓存回放。</li><li>服务器路由：统一处理 HTTP 与 WebSocket，注入语言环境、CORS、认证、限流与审计。</li><li>审计日志：按类别写入 JSON Lines，支持查询与日期列表。</li><li>配置与配对：内存缓存、写锁保护、敏感字段落盘混淆、默认安全值。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L229" target="_blank" rel="noreferrer">agent/src/security.js#L62-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L760" target="_blank" rel="noreferrer">agent/src/security.js#L285-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L177-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L177-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L7-L12" target="_blank" rel="noreferrer">agent/src/logger.js#L7-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>Agent 作为本地服务，对外暴露两类通道：</p><ul><li>HTTP：用于配对、状态、文件操作、命令执行、RAG、MCP、技能、日志查询等。</li><li>WebSocket：用于命令执行的实时流式输出与状态回放。</li></ul><p>所有需要认证的请求在路由层先校验 <code>Authorization</code> 头，再调用 <code>verifyToken</code> 获取扩展 ID；随后根据具体接口进行路径或命令安全检查，并记录审计日志。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展&quot;
participant Srv as &quot;HTTP 服务器&quot;
participant Auth as &quot;认证模块&quot;
participant Sec as &quot;安全模块&quot;
participant Log as &quot;审计日志&quot;
participant Exec as &quot;命令执行器&quot;
Ext-&gt;&gt;Srv : &quot;POST /api/pair {code, extensionId}&quot;
Srv-&gt;&gt;Auth : &quot;handlePairRequest(code, extensionId)&quot;
Auth--&gt;&gt;Srv : &quot;{success, token|error}&quot;
Srv-&gt;&gt;Log : &quot;logAuth(pair_success|pair_failed)&quot;
Srv--&gt;&gt;Ext : &quot;配对结果&quot;
Ext-&gt;&gt;Srv : &quot;GET /api/status/detail (Bearer token)&quot;
Srv-&gt;&gt;Auth : &quot;verifyToken(token)&quot;
Auth--&gt;&gt;Srv : &quot;extensionId or null&quot;
Srv--&gt;&gt;Ext : &quot;平台与工作目录信息&quot;
Ext-&gt;&gt;Srv : &quot;POST /api/exec (command, cwd)&quot;
Srv-&gt;&gt;Sec : &quot;checkCommand(command, force)&quot;
Sec--&gt;&gt;Srv : &quot;{safe, level}&quot;
alt &quot;deny&quot;
Srv-&gt;&gt;Log : &quot;logSecurity(exec_denied)&quot;
Srv--&gt;&gt;Ext : &quot;拒绝&quot;
else &quot;confirm&quot;
Srv--&gt;&gt;Ext : &quot;需要用户确认&quot;
else &quot;allow&quot;
Srv-&gt;&gt;Exec : &quot;executeCommand(command, cwd)&quot;
Exec--&gt;&gt;Ext : &quot;execId + 流式 stdout/stderr&quot;
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L167-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L167-L172</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="认证与配对机制" tabindex="-1">认证与配对机制 <a class="header-anchor" href="#认证与配对机制" aria-label="Permalink to &quot;认证与配对机制&quot;">​</a></h3><p>认证流程围绕“配对码 + 扩展 ID → Bearer Token”展开：</p><ul><li>配对码生成：使用密码学安全的随机字节，从排除易混淆字符的字符表中选取 6 位编码，抗暴力猜测。</li><li>配对码轮换：启动时立即生成初始配对码；定时任务根据是否有配对记录与最近活跃认证决定是否停止或继续轮换。</li><li>一次性使用：配对成功后立即轮换配对码，防止重复利用。</li><li>失败锁定：连续失败达到阈值后临时锁定一段时间，并在锁定时立即轮换配对码使已观测码失效。</li><li>Token 验证：每次请求遍历配对记录比对 token，成功则更新最后活跃时间，返回扩展 ID。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;启动&quot;]) --&gt; Gen[&quot;生成初始配对码&quot;]
Gen --&gt; Timer[&quot;启动定时轮换任务&quot;]
Timer --&gt; Check{&quot;有配对且最近活跃?&quot;}
Check --&gt; |是| StopRotate[&quot;停止轮换配对码&quot;]
Check --&gt; |否| Rotate[&quot;重新生成配对码&quot;]
Rotate --&gt; Timer
StopRotate --&gt; Timer
PairReq[&quot;收到配对请求&quot;] --&gt; Validate[&quot;校验 code 与 extensionId&quot;]
Validate --&gt; Locked{&quot;是否处于锁定窗口?&quot;}
Locked --&gt; |是| DenyLock[&quot;拒绝：过于频繁&quot;]
Locked --&gt; |否| Match{&quot;code 匹配当前配对码?&quot;}
Match --&gt; |否| IncFail[&quot;失败计数+1&quot;]
IncFail --&gt; Threshold{&quot;达到失败阈值?&quot;}
Threshold --&gt; |是| Lock[&quot;设置锁定时间并轮换配对码&quot;]
Threshold --&gt; |否| InvalidCode[&quot;返回无效配对码&quot;]
Match --&gt; |是| ResetFail[&quot;重置失败计数&quot;]
ResetFail --&gt; Exists{&quot;是否已有配对?&quot;}
Exists --&gt; |是| Rotated[&quot;轮换配对码并返回已有 token&quot;]
Exists --&gt; |否| Save[&quot;生成新 token 并保存配对&quot;]
Save --&gt; Rotated
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L53-L60" target="_blank" rel="noreferrer">agent/src/auth.js#L53-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L75-L102" target="_blank" rel="noreferrer">agent/src/auth.js#L75-L102</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L484" target="_blank" rel="noreferrer">agent/src/server.js#L474-L484</a></li></ul><h3 id="token-验证与会话管理" tabindex="-1">Token 验证与会话管理 <a class="header-anchor" href="#token-验证与会话管理" aria-label="Permalink to &quot;Token 验证与会话管理&quot;">​</a></h3><ul><li>会话语义：Agent 端不维护传统意义上的长会话对象，而是以“配对记录中的 token”作为凭据；每次请求校验 token 并刷新最后活跃时间。</li><li>活跃窗口：5 分钟内有过认证视为扩展在线，影响配对码是否继续轮换。</li><li>心跳接口：<code>/api/heartbeat</code> 仅需认证，用于维持扩展在线状态，不返回敏感信息。</li><li>令牌生命周期：配对成功即生成 32 字节随机十六进制 token，持久化到 <code>pairings.json</code>；配对码轮换不影响已配对 token，但会阻断新的配对尝试。</li></ul><pre class="mermaid">stateDiagram-v2
[*] --&gt; 未配对
未配对 --&gt; 配对中 : &quot;提交配对码&quot;
配对中 --&gt; 已配对 : &quot;配对成功&quot;
配对中 --&gt; 被锁定 : &quot;连续失败过多&quot;
已配对 --&gt; 活跃 : &quot;心跳或认证刷新 lastAuthTime&quot;
活跃 --&gt; 离线 : &quot;超过活跃窗口&quot;
离线 --&gt; 可配对 : &quot;配对码轮换完成&quot;
被锁定 --&gt; 可配对 : &quot;锁定时间到期&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L48" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L117-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L117-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L550-L553" target="_blank" rel="noreferrer">agent/src/server.js#L550-L553</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L117-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L117-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L553" target="_blank" rel="noreferrer">agent/src/server.js#L537-L553</a></li></ul><h3 id="权限控制系统与命令白名单" tabindex="-1">权限控制系统与命令白名单 <a class="header-anchor" href="#权限控制系统与命令白名单" aria-label="Permalink to &quot;权限控制系统与命令白名单&quot;">​</a></h3><p>命令安全采用分级策略：</p><ul><li>黑名单：绝对禁止，不可绕过，包括磁盘破坏、系统目录递归删除、系统文件覆盖、恶意管道执行、fork bomb、shebang 直接执行等。</li><li>灰名单：需用户确认，包括提权命令、全局安装、危险权限变更、原始写入/销毁、网络外联、进程操作、系统服务、脚本解释器执行外部文件、Windows 高危命令等。</li><li>白名单：通过检查的命令视为允许。</li></ul><p>命令解析不仅检查整串，还拆分链式命令、剥壳包装器（如 <code>sudo</code>、<code>env</code>、<code>timeout</code>）、归一化路径目标、提取解释器内联载荷与命令替换内容，逐段判定。</p><pre class="mermaid">flowchart TD
Entry[&quot;接收命令&quot;] --&gt; Normalize[&quot;清理空白与换行&quot;]
Normalize --&gt; Scopes[&quot;收集子命令范围&lt;br/&gt;整串 + 拆分段 + 内联载荷 + 替换内容&quot;]
Scopes --&gt; Blacklist{&quot;命中黑名单?&quot;}
Blacklist --&gt; |是| Deny[&quot;拒绝：绝对禁止&quot;]
Blacklist --&gt; |否| HardPath{&quot;命令包含硬阻止路径?&quot;}
HardPath --&gt; |是| Deny
HardPath --&gt; |否| Force{&quot;force 模式?&quot;}
Force --&gt; |是| Allow[&quot;允许：跳过灰名单&quot;]
Force --&gt; |否| Graylist{&quot;命中灰名单?&quot;}
Graylist --&gt; |是| Confirm[&quot;需要用户确认&quot;]
Graylist --&gt; |否| Allow
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L653-L683" target="_blank" rel="noreferrer">agent/src/security.js#L653-L683</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L760" target="_blank" rel="noreferrer">agent/src/security.js#L285-L760</a></li></ul><h3 id="文件路径沙箱与输入验证" tabindex="-1">文件路径沙箱与输入验证 <a class="header-anchor" href="#文件路径沙箱与输入验证" aria-label="Permalink to &quot;文件路径沙箱与输入验证&quot;">​</a></h3><p>路径检查流程：</p><ul><li>规范化路径格式，处理 Windows 盘符大小写、MSYS/Git Bash 风格路径、反斜杠统一。</li><li>展开 <code>~</code> 为用户主目录。</li><li>优先硬阻止 Agent 核心敏感文件与目录。</li><li>放行记忆存储目录与工作目录。</li><li>对 <code>allowedPaths</code> 做前缀匹配，再用 <code>realpath</code> 解析符号链接并再次校验。</li><li>返回允许结果与规范化后的路径，或拒绝原因。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;输入路径&quot;] --&gt; Norm[&quot;规范化路径格式&quot;]
Norm --&gt; Tilde{&quot;是否 ~ 或 ~/ ?&quot;}
Tilde --&gt; |是| Expand[&quot;展开为主目录&quot;]
Tilde --&gt; |否| Abs{&quot;是否绝对路径?&quot;}
Abs --&gt; |是| ResolveAbs[&quot;resolve 绝对路径&quot;]
Abs --&gt; |否| ResolveWork[&quot;resolve 工作目录 + 相对路径&quot;]
Expand --&gt; ResolveWork
ResolveAbs --&gt; NormalizePath[&quot;normalize 路径&quot;]
ResolveWork --&gt; NormalizePath
NormalizePath --&gt; HardBlock{&quot;是否硬阻止?&quot;}
HardBlock --&gt; |是| DenyHard[&quot;拒绝：核心敏感文件&quot;]
HardBlock --&gt; |否| MemoryCheck{&quot;是否在记忆目录?&quot;}
MemoryCheck --&gt; |是| AllowMem[&quot;允许：记忆目录&quot;]
MemoryCheck --&gt; |否| WorkdirCheck{&quot;是否在工作目录?&quot;}
WorkdirCheck --&gt; |是| RealpathWork[&quot;realpath 校验并再次硬阻止&quot;]
RealpathWork --&gt; AllowWork[&quot;允许：工作目录&quot;]
WorkdirCheck --&gt; |否| AllowedPrefix{&quot;是否在 allowedPaths 前缀?&quot;}
AllowedPrefix --&gt; |否| DenyPrefix[&quot;拒绝：不在允许目录&quot;]
AllowedPrefix --&gt; |是| RealpathAllowed[&quot;realpath 校验并再次前缀匹配&quot;]
RealpathAllowed --&gt; AllowAllowed[&quot;允许：白名单路径&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L40-L60" target="_blank" rel="noreferrer">agent/src/security.js#L40-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L40-L60" target="_blank" rel="noreferrer">agent/src/security.js#L40-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h3 id="命令执行器与超时策略" tabindex="-1">命令执行器与超时策略 <a class="header-anchor" href="#命令执行器与超时策略" aria-label="Permalink to &quot;命令执行器与超时策略&quot;">​</a></h3><p>命令执行器负责：</p><ul><li>选择 Shell：根据平台与环境变量探测可用 shell，回退到已知路径或原生 cmd。</li><li>环境变量白名单：仅透传必要环境变量，强制关闭彩色输出与终端交互特性。</li><li>子进程管理：记录运行中进程、输出缓冲区上限、已完成进程缓存回放。</li><li>超时策略：支持受管模式（协商 timeoutMs）与旧模式；期内无输出视为挂起即杀，有输出则按预算封顶逐步延长。</li><li>跨平台终止：Unix 使用进程组信号，Windows 使用 taskkill 递归终止。</li></ul><pre class="mermaid">sequenceDiagram
participant Srv as &quot;服务器&quot;
participant Exec as &quot;执行器&quot;
participant Proc as &quot;子进程&quot;
participant WS as &quot;WebSocket 客户端&quot;
Srv-&gt;&gt;Exec : &quot;executeCommand(command, cwd, wsClient)&quot;
Exec-&gt;&gt;Exec : &quot;pickShell() + buildSafeEnv()&quot;
Exec-&gt;&gt;Proc : &quot;spawn(shell, args, command)&quot;
Proc--&gt;&gt;Exec : &quot;stdout/stderr 数据&quot;
Exec-&gt;&gt;WS : &quot;广播 stdout/stderr&quot;
Proc--&gt;&gt;Exec : &quot;close/error&quot;
Exec-&gt;&gt;Exec : &quot;armTimeout() 决策 extend/kill&quot;
Exec--&gt;&gt;Srv : &quot;onComplete({execId, exitCode, killed})&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L177-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L177-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li></ul><h3 id="审计日志、安全事件监控与异常检测" tabindex="-1">审计日志、安全事件监控与异常检测 <a class="header-anchor" href="#审计日志、安全事件监控与异常检测" aria-label="Permalink to &quot;审计日志、安全事件监控与异常检测&quot;">​</a></h3><p>审计日志模块提供：</p><ul><li>分类日志：认证、文件、命令、安全、系统。</li><li>JSON Lines 格式，按日轮转，自动清理旧日志与大文件。</li><li>控制台输出开关，便于前台调试。</li><li>查询接口：按日期、分类、分页查询日志条目。</li></ul><p>安全事件监控体现在：</p><ul><li>认证失败、路径越界、命令拒绝、重启/更新操作、npm 安装异常等均记录日志。</li><li>服务器级异常捕获返回通用错误，避免泄露内部细节。</li></ul><pre class="mermaid">flowchart TD
Event[&quot;安全/认证/文件/命令/系统事件&quot;] --&gt; Logger[&quot;logger.log(level, category, action, details)&quot;]
Logger --&gt; Console{&quot;是否启用控制台输出?&quot;}
Console --&gt; |是| Stderr[&quot;stderr 输出可读日志&quot;]
Console --&gt; |否| SkipConsole[&quot;跳过控制台&quot;]
Logger --&gt; File[&quot;appendFileSync(agent-YYYY-MM-DD.log)&quot;]
File --&gt; Cleanup[&quot;定期清理旧日志与大文件&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L172</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L95-L123" target="_blank" rel="noreferrer">agent/src/logger.js#L95-L123</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L183-L211" target="_blank" rel="noreferrer">agent/src/logger.js#L183-L211</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L7-L12" target="_blank" rel="noreferrer">agent/src/logger.js#L7-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L172</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L183-L211" target="_blank" rel="noreferrer">agent/src/logger.js#L183-L211</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>server.js 依赖 auth.js、security.js、executor.js、logger.js、config.js 等模块，并在请求入口注入语言环境。</li><li>auth.js 依赖 config.js 读取/保存配对记录，依赖 i18n 与系统语言检测。</li><li>security.js 依赖 config.js 获取 workdir 与 allowedPaths，依赖 i18n 返回本地化拒绝原因。</li><li>executor.js 依赖 config.js 获取默认超时与工作目录，依赖 i18n 返回本地化错误消息。</li><li>logger.js 独立于业务逻辑，提供统一日志写入与查询能力。</li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Auth[&quot;auth.js&quot;]
Server --&gt; Security[&quot;security.js&quot;]
Server --&gt; Executor[&quot;executor.js&quot;]
Server --&gt; Logger[&quot;logger.js&quot;]
Server --&gt; Config[&quot;config.js&quot;]
Auth --&gt; Config
Security --&gt; Config
Executor --&gt; Config
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L23" target="_blank" rel="noreferrer">agent/src/server.js#L13-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L3-L5" target="_blank" rel="noreferrer">agent/src/auth.js#L3-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L5-L6" target="_blank" rel="noreferrer">agent/src/security.js#L5-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L6-L7" target="_blank" rel="noreferrer">agent/src/executor.js#L6-L7</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L23" target="_blank" rel="noreferrer">agent/src/server.js#L13-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L3-L5" target="_blank" rel="noreferrer">agent/src/auth.js#L3-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L5-L6" target="_blank" rel="noreferrer">agent/src/security.js#L5-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L6-L7" target="_blank" rel="noreferrer">agent/src/executor.js#L6-L7</a></li></ul><h2 id="性能与资源控制" tabindex="-1">性能与资源控制 <a class="header-anchor" href="#性能与资源控制" aria-label="Permalink to &quot;性能与资源控制&quot;">​</a></h2><ul><li>输出缓冲上限：命令 stdout/stderr 累计上限为 5MB，超限后标记截断并广播提示。</li><li>总超时预算：受管模式下最大延长次数与总预算封顶对齐扩展端 toolTimeout 上限，避免无限延长。</li><li>日志清理：每 60 秒检查一次，保留最多 30 个日志文件，单文件超过 10MB 自动删除。</li><li>配置缓存：配置与配对记录带 mtime 缓存，减少频繁 IO。</li><li>写锁保护：配置与配对写入加异步写锁，防止并发覆盖。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L96-L116" target="_blank" rel="noreferrer">agent/src/executor.js#L96-L116</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L166-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L166-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L8-L11" target="_blank" rel="noreferrer">agent/src/logger.js#L8-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L95-L123" target="_blank" rel="noreferrer">agent/src/logger.js#L95-L123</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L43-L51" target="_blank" rel="noreferrer">agent/src/config.js#L43-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L64-L73" target="_blank" rel="noreferrer">agent/src/config.js#L64-L73</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>无法配对： <ul><li>检查配对码是否过期或被轮换；查看 Agent 终端输出的配对码。</li><li>检查连续失败是否触发锁定；等待锁定时间后重试。</li><li>确认扩展 ID 是否正确传入。</li></ul></li><li>认证失败： <ul><li>确认请求头携带正确的 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>检查 token 是否仍存在于 <code>pairings.json</code>。</li><li>查看安全日志中的认证失败记录。</li></ul></li><li>命令被拒绝： <ul><li>若为黑名单命令，无法绕过；需修改命令。</li><li>若为灰名单命令，需在扩展侧确认放行。</li><li>检查命令是否包含硬阻止路径。</li></ul></li><li>命令执行卡住： <ul><li>检查是否进入受管模式的延长策略；观察输出是否为空导致静默杀进程。</li><li>检查 WebSocket 连接是否断开；延迟连接的客户端可回放已完成进程输出。</li></ul></li><li>日志缺失： <ul><li>检查日志目录是否存在与权限；确认日志写入是否被其他进程占用。</li><li>使用日志查询接口按日期与分类过滤。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L429-L453" target="_blank" rel="noreferrer">agent/src/executor.js#L429-L453</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L183-L211" target="_blank" rel="noreferrer">agent/src/logger.js#L183-L211</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent 的认证与授权体系以配对码与 Bearer Token 为核心，结合路径沙箱与命令分级策略，形成多层安全边界。认证流程具备一次性配对码、失败锁定与活跃窗口机制；命令执行具备黑名单绝对禁止、灰名单用户确认与白名单放行；审计日志提供可查询的分类事件记录。整体设计强调本地安全、最小权限与可观测性，适合在 Chrome 扩展与本地代理的双进程架构中使用。</p><h2 id="附录-安全配置、最佳实践与审计清单" tabindex="-1">附录：安全配置、最佳实践与审计清单 <a class="header-anchor" href="#附录-安全配置、最佳实践与审计清单" aria-label="Permalink to &quot;附录：安全配置、最佳实践与审计清单&quot;">​</a></h2><h3 id="安全配置要点" tabindex="-1">安全配置要点 <a class="header-anchor" href="#安全配置要点" aria-label="Permalink to &quot;安全配置要点&quot;">​</a></h3><ul><li>监听地址：默认仅监听 <code>127.0.0.1</code>，如需远程连接需显式修改 host 参数。</li><li>工作目录与白名单：默认工作目录与 skills 目录自动加入允许列表；建议将 allowedPaths 限制在项目目录。</li><li>文件大小限制：读取默认 50MB，上传流式最大 200MB；可根据需求调整 fileMaxSize。</li><li>命令超时：默认 300 秒；可通过 execOpts.timeoutMs 协商受管模式。</li><li>RAG 内网访问：默认拒绝内网，需同时开启 allowPrivateNetwork 且 allowedPrivateHosts 命中才放行。</li><li>记忆嵌入 API Key：内存明文、落盘混淆；任何对外响应脱敏。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L138-L149" target="_blank" rel="noreferrer">agent/src/config.js#L138-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L160-L165" target="_blank" rel="noreferrer">agent/src/config.js#L160-L165</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L249-L268" target="_blank" rel="noreferrer">agent/src/config.js#L249-L268</a></li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>始终通过扩展端发起配对，不要手动编辑 <code>pairings.json</code>。</li><li>不要在仓库中硬编码真实 token；集成测试应从环境变量或本机配对记录取得 token。</li><li>对高危命令尽量在扩展侧引导用户确认，避免频繁 force 放行。</li><li>定期检查审计日志中的安全事件，关注认证失败、路径越界与命令拒绝。</li><li>保持 Agent 版本与扩展版本同步，修改 Agent 源码后必须重启进程。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js#L18-L36" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js#L18-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4688-L4697" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4688-L4697</a></li></ul><h3 id="安全审计清单" tabindex="-1">安全审计清单 <a class="header-anchor" href="#安全审计清单" aria-label="Permalink to &quot;安全审计清单&quot;">​</a></h3><ul><li>认证： <ul><li>配对码是否动态生成且一次性使用？</li><li>失败锁定是否生效？</li><li>Token 是否仅在内存中比对，不落盘明文？</li></ul></li><li>授权： <ul><li>所有敏感接口是否要求 Bearer Token？</li><li>健康检查与配对接口是否限制来源？</li></ul></li><li>路径： <ul><li>是否启用 realpath 防符号链接绕过？</li><li>是否硬阻止 Agent 核心敏感文件？</li><li>是否限制 allowedPaths 与工作目录？</li></ul></li><li>命令： <ul><li>黑名单是否覆盖磁盘破坏、系统目录删除、系统文件覆盖、恶意管道执行？</li><li>灰名单是否覆盖提权、全局安装、危险权限变更、网络外联、进程操作？</li><li>是否支持链式命令、包装器剥壳、内联载荷与命令替换检查？</li></ul></li><li>执行： <ul><li>是否使用环境变量白名单？</li><li>是否限制输出缓冲区与总超时预算？</li><li>是否支持跨平台进程终止？</li></ul></li><li>审计： <ul><li>是否记录认证、文件、命令、安全、系统事件？</li><li>日志是否按日轮转并自动清理？</li><li>是否提供日志查询接口？</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L242-L266" target="_blank" rel="noreferrer">agent/src/server.js#L242-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L229" target="_blank" rel="noreferrer">agent/src/security.js#L62-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L760" target="_blank" rel="noreferrer">agent/src/security.js#L285-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L177-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L177-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L172</a></li></ul>`,106)])])}const L=t(l,[["render",o]]);export{b as __pageData,L as default};
